async function fixtureWrites(page){return page.evaluate(()=>window.NamelessQaFixture.writes);}
async function workspaceState(page){return page.evaluate(()=>window.NamelessMapWorkspace.active.getState());}
async function fillField(page,id,value){const field=page.locator(id);await field.fill(String(value));await field.press('Tab');}
async function clickImagePoint(page,u,v){const p=await page.evaluate(({u,v})=>{const b=window.NamelessMapPage.active,c=b.map.latLngToContainerPoint(b.getLatLng({u,v})),r=document.querySelector('#game-map').getBoundingClientRect();return{x:r.x+c.x,y:r.y+c.y,left:r.x,top:r.y,width:r.width,height:r.height}},{u,v});assert.ok(p.x>p.left&&p.x<p.left+p.width&&p.y>p.top&&p.y<p.top+p.height);await page.mouse.click(p.x,p.y);}
async function draft(page){return page.evaluate(()=>window.NamelessMapRegions.active.editor.getDraft());}
