 try{await visitAdmin(page);await page.waitForTimeout(850);const handle=page.locator('.map-region-vertex').first(),button=handle.locator('button');await (await button.count()?button:handle).focus();await page.keyboard.press('Shift+ArrowRight');await page.waitForTimeout(650);await page.locator('[data-region-action="undo"]').click();await page.waitForTimeout(650);await page.locator('[data-workspace-mode="markers"]').click();await page.locator('#workspace-marker-new').click();await fillField(page,'#workspace-marker-title','QA Campement de contrôle');await page.locator('#map-recenter').click();await page.waitForTimeout(700);await page.locator('#workspace-marker-place').click();await clickImagePoint(page,.49,.57);await page.waitForTimeout(700);await page.locator('#workspace-marker-local').click();await page.waitForTimeout(700);await page.locator('#workspace-marker-publish').click();await page.waitForFunction(()=>!window.NamelessMapWorkspace.active.getState().busy);await page.waitForTimeout(900);await page.locator('[data-workspace-mode="atlas"]').click();await page.waitForTimeout(900);await page.locator('[data-workspace-mode="regions"]').click();await page.waitForTimeout(950);const video=page.video();await ctx.close();const file=await video.path();fs.copyFileSync(file,path.join(output,'admin-map-editor-motion.webm'));fs.unlinkSync(file);fs.rmdirSync(raw);report.adminVideo={file:'admin-map-editor-motion.webm',kind:'Actual components with prominently labelled in-memory QA session; no production writes'};return report.adminVideo;}catch(error){await ctx.close();throw error;}
